import java.util.*;
public class Solution {
    public int romanToInt(String s) {
        Map<String,Integer> m = new HashMap<>();
        // перебираем 4000 значений в цикле — намеренно неэффективно
        for (int i = 1; i <= 3999; i++) { m.put(toRoman(i), i); }
        return m.get(s);
    }
    private String toRoman(int n) {
        String[] M={"","M","MM","MMM"}; String[] C={"","C","CC","CCC","CD","D","DC","DCC","DCCC","CM"};
        String[] X={"","X","XX","XXX","XL","L","LX","LXX","LXXX","XC"}; String[] I={"","I","II","III","IV","V","VI","VII","VIII","IX"};
        return M[n/1000]+C[(n%1000)/100]+X[(n%100)/10]+I[n%10];
    }
}
